//! Tauri command surface: 29 thin forwards.
//!
//! Every command does the same three things — take `State<MoinState>`, resolve
//! the engine, forward to it — plus the one event the engine cannot emit on its
//! own (settings and categories are saved by the engine but announced here, so
//! the engine stays free of `AppHandle`).
//!
//! These names are mirrored in `src-tauri/src/invoke.rs`, `build.rs`,
//! `capabilities/default.json` and `permissions/autogenerated/moin_*.toml`.
//! Renaming one without the other three breaks the ACL at runtime.

use std::collections::BTreeMap;
use std::path::PathBuf;

use serde::Serialize;
use tauri::{AppHandle, State};

use crate::engine::Engine;
use crate::error::{MoinError, MoinResult};
use crate::models::{BackendInfo, Category, RpcStatus, Settings, Task, ToolStatus};
use crate::state::{self, MoinState};

#[derive(Debug, Clone, Serialize)]
pub struct AppInfo {
    pub name: String,
    pub version: String,
}

/// The folder a download lands in when the caller does not name one: the
/// configured default, falling back to the platform Downloads directory.
fn default_dir(state: &MoinState, engine: &Engine) -> PathBuf {
    engine
        .settings()
        .download_dir
        .filter(|value| !value.trim().is_empty())
        .map(PathBuf::from)
        .unwrap_or_else(|| state.downloads_dir.clone())
}

#[tauri::command]
pub fn moin_app_info(app: AppHandle) -> AppInfo {
    let info = app.package_info();
    AppInfo {
        name: info.name.clone(),
        version: info.version.to_string(),
    }
}

#[tauri::command]
pub async fn moin_list_downloads(state: State<'_, MoinState>) -> MoinResult<Vec<Task>> {
    Ok(state.engine().await?.list())
}

#[tauri::command]
pub async fn moin_add_download(
    state: State<'_, MoinState>,
    url: String,
    category: Option<String>,
    headers: Option<BTreeMap<String, String>>,
    filename: Option<String>,
) -> MoinResult<Task> {
    let engine = state.engine().await?;
    let dir = default_dir(&state, &engine);
    engine
        .add_http(url, dir, category, headers.unwrap_or_default(), filename)
        .await
}

