#[tauri::command]
pub async fn moin_set_settings(
    state: State<'_, MoinState>,
    settings: Settings,
) -> MoinResult<()> {
    let engine = state.engine().await?;
    engine.set_settings(settings.clone())?;
    state::apply_settings(&settings);
    state::emit_settings_changed(&state.app, &settings);
    Ok(())
}

#[tauri::command]
pub async fn moin_patch_settings(
    state: State<'_, MoinState>,
    patch: serde_json::Value,
) -> MoinResult<Settings> {
    let engine = state.engine().await?;
    let mut value = serde_json::to_value(engine.settings())
        .map_err(|error| MoinError::internal(error.to_string()))?;
    let patch = patch
        .as_object()
        .ok_or_else(|| MoinError::invalid_input("patch", "Expected an object."))?;
    let object = value
        .as_object_mut()
        .ok_or_else(|| MoinError::internal("Settings could not be encoded."))?;
    for (key, incoming) in patch {
        if !object.contains_key(key) {
            return Err(MoinError::invalid_input("patch", format!("Unknown setting '{key}'.")));
        }
        object.insert(key.clone(), incoming.clone());
    }
    let next: Settings = serde_json::from_value(value)
        .map_err(|error| MoinError::invalid_input("patch", error.to_string()))?;
    engine.set_settings(next.clone())?;
    state::apply_settings(&next);
    state::emit_settings_changed(&state.app, &next);
    Ok(next)
}

